-- Generated by tools/build_replay_queries.py; SQL003 stays frozen.
-- Existing complete proofs validate once; first/incomplete capture is unchanged.
BEGIN;
DO $guard$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang
  WHERE p.oid='ingestion.begin_source_graph_projection(text)'::regprocedure AND l.lanname='plpgsql'
  AND p.prorettype='boolean'::regtype AND NOT p.prosecdef
  AND p.proconfig=ARRAY['jit=off']::text[] AND md5(p.prosrc) IN ('90182558760e51fdd0a03f26f4fe658c','dc79a2ec9c046cc8bac644701940982a'))
 THEN RAISE EXCEPTION 'SOURCE_GRAPH_REPLAY_CANONICAL_DRIFT'; END IF;
END $guard$;
CREATE OR REPLACE FUNCTION ingestion.begin_source_graph_projection_v3_compat(jobs text) RETURNS boolean
LANGUAGE plpgsql SET jit=off AS $$
DECLARE u ingestion.run; m record;
BEGIN
 SELECT * INTO u FROM ingestion.run WHERE run_id=jobs AND state='READY' AND mode<>'SMOKE';
 IF NOT FOUND OR EXISTS(SELECT 1 FROM ingestion.source_graph_validation_issue(jobs))
 THEN RAISE EXCEPTION 'SOURCE_GRAPH_REQUIRES_EXACT_READY_RUN'; END IF;
 INSERT INTO ingestion.source_graph_record_evidence SELECT * FROM ingestion.source_graph_live_record_evidence
 WHERE run_id=jobs ON CONFLICT DO NOTHING;
 INSERT INTO ingestion.source_graph_membership SELECT run_id,record_id,identity_id,field,kind,code FROM ingestion.source_graph_reference
 WHERE run_id=jobs ON CONFLICT DO NOTHING;
 SELECT * INTO m FROM ingestion.source_graph_manifest(jobs,true);
 INSERT INTO ingestion.source_graph_projection(run_id,source_id,state,loader_version,record_count,reference_count,content_sha256,started_at)
 VALUES(jobs,u.source_id,'LOADING','hop-graph-batchfree-v1',m.record_count,m.reference_count,m.content_sha256,clock_timestamp())
 ON CONFLICT(run_id) DO UPDATE SET state='LOADING',verified_at=NULL,error_code=NULL,started_at=clock_timestamp();
 PERFORM ingestion.assert_source_graph_content(jobs);
 RETURN true;
END $$;

CREATE OR REPLACE FUNCTION ingestion.begin_source_graph_projection(jobs text) RETURNS boolean
LANGUAGE plpgsql SET jit=off AS $$
DECLARE u ingestion.run; p ingestion.source_graph_projection;
BEGIN
 -- Acquire the retention gate before live reads or proof row locks. This
 -- prevents archival between eligibility validation and replay publication.
 PERFORM retention.gate();
 -- Retained archived proofs are valid for readback, never a new live replay.
 SELECT * INTO u FROM ingestion.run WHERE run_id=jobs AND state='READY' AND mode<>'SMOKE';
 IF NOT FOUND THEN RAISE EXCEPTION 'SOURCE_GRAPH_REQUIRES_EXACT_READY_RUN'; END IF;
 SELECT * INTO p FROM ingestion.source_graph_projection WHERE run_id=jobs FOR UPDATE;
 IF FOUND
  AND p.record_count=(SELECT count(*) FROM ingestion.source_graph_record_evidence WHERE run_id=jobs)
  AND p.reference_count=(SELECT count(*) FROM ingestion.source_graph_membership WHERE run_id=jobs)
 THEN
  -- Authoritative validation still compares captured and live content, before
  -- changing state. UPDATE retains immutable-proof and retention guards.
  PERFORM ingestion.assert_source_graph_content(jobs);
  UPDATE ingestion.source_graph_projection SET state='LOADING',verified_at=NULL,
   error_code=NULL,started_at=clock_timestamp() WHERE run_id=jobs;
  RETURN true;
 END IF;
 -- First capture and incomplete captured rows keep the exact SQL003 behavior.
 RETURN ingestion.begin_source_graph_projection_v3_compat(jobs);
END $$;
COMMIT;
